"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["13961"],{379732(e){e.exports=JSON.parse('{"id":11442,"title":"\u56FD\u5916\u6587\u732E\u53D9\u8FF03","description":"\u8BF7\u57FA\u4E8E\u524D\u9762\u7684\u5199\u4F5C\u8981\u6C42\u5E2E\u6211\u5B8C\u6210\u56FD\u5916\u7814\u7A76\u73B0\u72B6\u90E8\u5206,\u8BF7\u5728\u6570\u636E\u5E931Google Scholar\u3001 PubMed\u3001WOS)\u68C0\u7D22\u4E0E\u6211\u7684\u4E3B\u9898\u76F8\u5173\u7684\u9AD8\u8D28\u91CF\u3001\u771F\u5B9E\u53EF\u9760\u7684\u53C2\u8003\u6587\u732E,! \u6709\u53C2\u8003\u6587\u732E\u5FC5\u987B\u771F\u5B9E\u53EF\u9A8C\u8BC1,\u5207\u52FF\u865A\u6784\u3002\u6240\u6709\u63D0\u4F9B\u7684\u53C2\u8003\u6587\u732E\u5FC5\u987B\u4E3A\u8FD15\u5E74(\u5373\u57FA\u4E8E\u5F53\u524D \u5E74\u4EFD,\u81EA2020\u5E74\u8D77)\u53D1\u8868\u7684\u671F\u520A\u8BBA\u6587,\u4E0D\u80FD\u662F\u65B0\u95FB\u62A5\u9053\u6216\u5176\u4ED6\u5185\u5BB9\u3002\u6BCF\u7BC7\u6587\u732E\u6309\u7167\u4F5C\u4E66 (XX\u5E74\u4EFD)\u7684\u5F62\u5F0F\u5F15\u51FA\u540E\u7EED\u5185\u5BB9\u5E76\u5728\u672B\u5C3E\u6807\u6CE8\u5F15\u7528\u5E8F\u53F7\u5982(1,\u8BF7\u6309\u7167GB/7714-201 \u6587\u6807\u51C6\u4EE5\u6587\u4E2D\u7684\u5F15|\u7528\u987A\u5E8F\u5217\u51FA\u53C2\u8003\u6587\u732E,\u5E76\u7ED9\u51FA\u6BCF\u7BC7\u6587\u732E\u7684\u539F\u6587\u94FE\u63A5,\u5199\u4F5C\u5185\u5BB9\u91CD\u70B9\u95F4\u56FD\u5916\u7814\u7A76\u7684\u7406\u8BBA\u6E90\u6D41,\u6F14\u8FDB\u8109\u7EDC\u4E0E\u65B9\u6CD5\u8BBA\u7279\u70B9,\u8BF4\u660E\u5176\u8D77\u6B65\u65F6\u95F4\u3001\u4E3B\u5BFC\u7684\u7406\u8BBA\u65B9\u6CD5/\u5206\u6790 \u67B6,\u4EE5\u53CA\u91C7\u7528\u4E86\u54EA\u4E9B\u6807\u5FD7\u6027\u7684\u7814\u7A76\u65B9\u6CD5(\u5982\u5927\u89C4\u6A21\u5B9E\u9A8C\u3001\u957F\u671F\u8FFD\u8E2A\u3001\u6570\u5B66\u6A21\u578B\u6784\u5EFA\u7B49) \u8BF7\u5448\u73B0\u5176\u4ECE\u57FA\u7840\u7406\u8BBA\u6784\u5EFA\u5230\u5E94\u7528\u62D3\u5C55,\u518D\u5230\u5F53\u524D\u7814\u7A76\u524D\u6CBF\u7684\u5B8C\u6574\u53D1\u5C55\u94FE\u6761\u3002","remark":"\u56FD\u5916\u6587\u732E\u53D9\u8FF03","notes":"\u56FD\u5916\u6587\u732E\u53D9\u8FF03","owner":"evantao@163.com","upvotes":2,"downvotes":0,"upvoteDifference":2,"updatedAt":"2026-04-13T20:39:05.394Z"}')}}]);